import {GestureEngine} from './gestures.js';
const $=id=>document.getElementById(id);
const engine=new GestureEngine();
const state={mode:'off',paused:false,step:0,selectedFile:'reference',page:1,selections:0,startedAt:null,completedAt:null,events:[],demoRun:0,sessionKind:'Practice'};
let stream,landmarker,frameId=0,lastVideoTime=-1,lastInference=0,lastSeen=0,hovered=null,toastTimer,cameraRun=0;
let holdMode=null,holdSince=0;
const localTime=()=>new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit',second:'2-digit'});
function log(message){state.events.unshift({message,time:localTime()});state.events=state.events.slice(0,30);renderActivity();}
function renderActivity(){const list=$('activity-list');list.replaceChildren();if(!state.events.length){const li=document.createElement('li');li.textContent='Your actions will appear here. Nothing is saved after you reload.';list.append(li);}for(const event of state.events){const li=document.createElement('li'),time=document.createElement('time');li.append(document.createTextNode(event.message));time.textContent=event.time;li.append(time);list.append(li);}}
function status(message,error=false){$('status').textContent=message;$('status').classList.toggle('error',error);}
function toast(message){clearTimeout(toastTimer);$('toast').textContent=message;$('toast').hidden=false;toastTimer=setTimeout(()=>$('toast').hidden=true,3500);}
function countSelection(){state.selections++;$('selection-count').textContent=`${state.selections} selection${state.selections===1?'':'s'}`;}
function startPractice(){state.startedAt??=performance.now();}
function updateTask(){const prompts=['Open the Reference files tab.','Open the Touchless interaction reference.','Read page 2, then mark it reviewed.','Practice complete. Reset to try again.'];$('task-instruction').textContent=prompts[state.step];$('task-count').textContent=`${state.step} / 3`;$('task-num').textContent=state.step===3?'✓':String(state.step+1).padStart(2,'0');}
function selectTab(name){if(!['overview','files','activity'].includes(name))throw new Error('Unknown record section.');document.querySelectorAll('[data-tab]').forEach(button=>{const active=button.dataset.tab===name;button.setAttribute('aria-selected',String(active));button.tabIndex=active?0:-1;$(button.dataset.tab).hidden=!active;});if(name==='files'&&state.step===0){startPractice();state.step=1;updateTask();}}
function openFile(which){state.selectedFile=which;state.page=1;$('file-list').hidden=true;$('document-view').hidden=false;if(which==='reference'&&state.step===1){state.step=2;updateTask();}log(`Opened ${which==='reference'?'interaction reference':'preparation notes'}`);renderDocument();}
function renderDocument(){
 const notes=state.selectedFile==='notes',second=state.page===2;
 $('document-title').textContent=notes?'Session preparation notes':'Touchless interaction reference';$('page-indicator').textContent=notes?'1 / 1':`${state.page} / 2`;
 $('previous-page').disabled=state.page===1;$('next-page').hidden=notes||second;$('review-button').hidden=notes||!second;$('review-button').disabled=state.step===3;
 // Authored demonstration text only. No user-generated HTML enters this surface.
 $('document-body').innerHTML=notes?`<p class="eyebrow">DEMO DOCUMENT B / SESSION PREPARATION</p><h3>Set up a comfortable practice space.</h3><p>Use an evenly lit room. Position the camera so that your hand and fingertips remain visible without stretching your arm.</p><h4>Test before relying on a gesture</h4><p>Start with a bare hand, then repeat the same task with your glove. Record the lighting, glove material, background, and any missed or accidental selections.</p><h4>Keep an alternative available</h4><p>Mouse and keyboard inputs remain available throughout this demonstration. Press Escape to stop camera tracking.</p><p class="doc-footer">Synthetic training content. No clinical instructions or patient information.</p>`:second?`<p class="eyebrow">DEMO DOCUMENT A / PAGE 02</p><h3>Make every selection deliberate.</h3><p>The pointer follows your index finger. Bring your thumb and index finger together briefly to select a highlighted control. Release fully before the next selection.</p><h4>What happens if tracking is lost?</h4><p>The pointer stops selecting when no hand is detected. Show an open hand before pinching again so the controller can re-arm.</p><h4>A clear stop is always available</h4><p>Press Space to pause or resume. Press Escape to stop and release the camera. A hidden browser tab also stops camera access.</p><h4>Finish this practice</h4><p>Select <strong>Mark reviewed</strong> below. This changes only this simulated record; it does not submit or approve a real document.</p><p class="doc-footer">End of demo document. You can reset the task and repeat it with a different input method.</p>`:`<p class="eyebrow">DEMO DOCUMENT A / PAGE 01</p><h3>Touchless interaction, one task at a time.</h3><p>This sample workspace explores a simple question: can someone navigate and review information without touching a keyboard or mouse?</p><h4>Keep the task focused</h4><p>The practice has three steps: open the reference files, open this document, and review its second page. Larger controls and visible selection feedback help make intent clear.</p><h4>Try scrolling</h4><p>Raise your index and middle fingers, with the other fingers folded. Move your hand up or down to scroll this document. Lower the middle finger to return to pointing.</p><h4>Evaluate the interaction</h4><p>Observe missed clicks, accidental selections, fatigue, and lost tracking. A working prototype does not establish glove reliability or clinical suitability.</p><p class="doc-footer">Continue to page 2 using the button below.</p>`;
 $('document-body').scrollTop=0;
}
function completeReview(){if(state.selectedFile!=='reference'||state.page!==2||state.step<2||state.step===3)return;state.step=3;state.completedAt=performance.now();$('record-status').textContent='Reviewed';$('record-status').classList.add('done');$('review-button').disabled=true;log('Marked demo reference reviewed');updateTask();toast('Practice complete. See Activity for your session.');}
function resetPractice(){state.step=0;state.selections=0;state.startedAt=null;state.completedAt=null;state.page=1;state.events=[];state.sessionKind='Practice';$('selection-count').textContent='0 selections';$('timing').textContent='Practice not started';$('record-status').textContent='Ready for review';$('record-status').classList.remove('done');$('file-list').hidden=false;$('document-view').hidden=true;selectTab('overview');renderActivity();updateTask();}
document.querySelectorAll('[data-tab]').forEach(button=>{button.addEventListener('click',()=>selectTab(button.dataset.tab));button.addEventListener('keydown',event=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const tabs=[...document.querySelectorAll('[data-tab]')];let idx=tabs.indexOf(button);idx=event.key==='Home'?0:event.key==='End'?tabs.length-1:(idx+(event.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;selectTab(tabs[idx].dataset.tab);tabs[idx].focus();});});
$('open-reference').addEventListener('click',()=>openFile('reference'));$('open-notes').addEventListener('click',()=>openFile('notes'));
$('back-files').addEventListener('click',()=>{$('file-list').hidden=false;$('document-view').hidden=true;});
$('next-page').addEventListener('click',()=>{state.page=2;renderDocument();log('Moved to reference page 2');});$('previous-page').addEventListener('click',()=>{state.page=1;renderDocument();log('Moved to reference page 1');});$('review-button').addEventListener('click',completeReview);
document.querySelectorAll('[data-gesture]').forEach(button=>button.addEventListener('click',()=>countSelection()));
$('reset-button').addEventListener('click',()=>{stopDemo();resetPractice();engine.reset();toast('Practice reset.');});
setInterval(()=>{if(state.startedAt!==null){const seconds=Math.max(0,((state.completedAt??performance.now())-state.startedAt)/1000);$('timing').textContent=`${state.sessionKind} · ${seconds.toFixed(1)}s ${state.completedAt?'completed':'elapsed'}`;}},200);
function clearPointer(){hovered?.classList.remove('gesture-hover');hovered=null;$('cursor').hidden=true;$('cursor').classList.remove('pinching');}
function pointer(x,y,pinch=false){const cursor=$('cursor');cursor.hidden=false;cursor.style.left=`${x}px`;cursor.style.top=`${y}px`;cursor.classList.toggle('pinching',pinch);const target=document.elementFromPoint(x,y)?.closest('[data-gesture]');if(hovered!==target){hovered?.classList.remove('gesture-hover');hovered=target&&!target.disabled?target:null;hovered?.classList.add('gesture-hover');}return hovered;}
function setMode(mode){state.mode=mode;document.body.classList.toggle('demo-active',mode==='demo');$('mode-label').textContent=mode==='camera'?'LIVE CAMERA':mode==='demo'?'GUIDED DEMO':'CAMERA OFF';$('live-indicator').classList.toggle('active',mode!=='off');}
function stopDemo(){state.demoRun++;if(state.mode!=='demo')return;setMode('off');clearPointer();$('demo-button').textContent='Try the guided demo';$('camera-caption').textContent='Camera is off';$('camera-empty').querySelector('strong').textContent='Your camera, your cursor';$('camera-empty').querySelector('span:last-child').textContent='Keep one hand in view.';$('gesture-label').textContent='Demo stopped';}
const wait=ms=>new Promise(resolve=>setTimeout(resolve,ms));
async function runDemo(){
 if(state.mode==='demo'){stopDemo();status('Guided demo stopped. Explore with mouse or keyboard.');return;}
 stopCamera(false);resetPractice();setMode('demo');state.sessionKind='Simulated demo';const run=++state.demoRun;$('demo-button').textContent='Stop guided demo';$('camera-caption').textContent='Simulated input · no camera';$('camera-empty').querySelector('strong').textContent='See the interaction';$('camera-empty').querySelector('span:last-child').textContent='Guided demo · simulated gestures';status('A scripted walkthrough is running. This demonstrates the interface, not hand recognition.');log('Started guided demo (simulated input)');
 const steps=[['tab-files','Point to Reference files'],['open-reference','Pinch to open the reference'],['next-page','Read the next page'],['review-button','Pinch to mark reviewed']];
 for(const [id,label]of steps){if(state.demoRun!==run)return;$('gesture-label').textContent=label;const el=$(id);el.scrollIntoView({behavior:'auto',block:'nearest'});let rect=el.getBoundingClientRect();pointer(rect.left+rect.width/2,rect.top+rect.height/2);await wait(1300);if(state.demoRun!==run)return;rect=el.getBoundingClientRect();pointer(rect.left+rect.width/2,rect.top+rect.height/2,true);el.click();await wait(700);}
 if(state.demoRun!==run)return;clearPointer();$('gesture-label').textContent='Guided demo complete';$('demo-button').textContent='Finish guided demo';status('Demo complete. Enable your camera to try the workflow with your own hand.');
}
$('demo-button').addEventListener('click',runDemo);
function stopCamera(showStatus=true){cameraRun++;cancelAnimationFrame(frameId);stream?.getTracks().forEach(track=>track.stop());stream=null;$('video').srcObject=null;$('overlay').getContext('2d').clearRect(0,0,$('overlay').width,$('overlay').height);landmarker?.close();landmarker=null;lastVideoTime=-1;lastInference=0;lastSeen=0;holdMode=null;holdSince=0;state.paused=false;engine.reset();clearPointer();$('camera-button').disabled=false;$('camera-button').textContent='Enable camera';$('tracking-controls').hidden=true;$('camera-empty').hidden=false;$('camera-caption').textContent='Camera is off';$('pause-button').textContent='Pause tracking';if(state.mode==='camera'){setMode('off');$('gesture-label').textContent='Camera stopped';if(showStatus){status('Camera stopped. Mouse and keyboard controls still work.');log('Stopped camera');}}}
function setPaused(paused){if(state.mode!=='camera')return;state.paused=paused;engine.reset();holdMode=null;holdSince=0;clearPointer();$('pause-button').textContent=paused?'Resume tracking':'Pause tracking';$('gesture-label').textContent=paused?'Paused · hold an open palm to resume':'Show your hand';$('mode-label').textContent=paused?'PAUSED':'LIVE CAMERA';status(paused?'Selections are paused. Hold an open palm for one second, press Space, or use Resume tracking.':'Show an open hand first, then point and pinch. Hold a fist for one second to pause.');log(paused?'Paused tracking':'Resumed tracking');}
async function startCamera(){
 if(!navigator.mediaDevices?.getUserMedia){status('Camera access needs a supported browser on HTTPS or localhost. The guided demo still works.',true);return;}
 stopDemo();stopCamera(false);resetPractice();state.sessionKind='Camera practice';const run=++cameraRun;$('camera-button').disabled=true;$('camera-button').textContent='Preparing camera…';status('Loading the hand-tracking model. Your browser will ask for camera access.');
 try{
  const {FilesetResolver,HandLandmarker}=await import('https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.21/vision_bundle.mjs');
  const files=await FilesetResolver.forVisionTasks('https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.21/wasm');
  const model=await HandLandmarker.createFromOptions(files,{baseOptions:{modelAssetPath:'https://storage.googleapis.com/mediapipe-models/hand_landmarker/hand_landmarker/float16/1/hand_landmarker.task',delegate:'CPU'},runningMode:'VIDEO',numHands:1,minHandDetectionConfidence:.65,minHandPresenceConfidence:.65,minTrackingConfidence:.65});
  if(cameraRun!==run){model.close();return;}landmarker=model;
  const media=await navigator.mediaDevices.getUserMedia({audio:false,video:{width:{ideal:640},height:{ideal:480},facingMode:'user'}});
  if(cameraRun!==run){media.getTracks().forEach(track=>track.stop());return;}stream=media;$('video').srcObject=stream;await $('video').play();if(cameraRun!==run)return;
  setMode('camera');$('camera-button').textContent='Camera connected';$('tracking-controls').hidden=false;$('camera-empty').hidden=true;$('camera-caption').textContent='Camera on · local processing';status('Show an open hand, then point to a control. Pinch briefly to select and release to re-arm.');log('Started local camera tracking');lastSeen=performance.now();
  media.getVideoTracks()[0].addEventListener('ended',()=>{if(cameraRun===run){stopCamera(false);status('Camera access ended. Enable the camera to reconnect.',true);}});frameId=requestAnimationFrame(trackHand);
 }catch(error){if(cameraRun!==run)return;stopCamera(false);const message=error?.name==='NotAllowedError'?'Camera permission was declined. Allow it in your browser settings or use the guided demo.':error?.name==='NotFoundError'?'No camera was found. Connect a camera or use the guided demo.':error?.name==='NotReadableError'?'The camera is busy or unavailable. Close other camera apps, then try again.':'Hand tracking could not start. Check your connection and camera support, then try again. The guided demo still works.';status(message,true);}
}
const edges=[[0,1],[1,2],[2,3],[3,4],[0,5],[5,6],[6,7],[7,8],[5,9],[9,10],[10,11],[11,12],[9,13],[13,14],[14,15],[15,16],[13,17],[0,17],[17,18],[18,19],[19,20]];
function drawHand(points){const canvas=$('overlay'),context=canvas.getContext('2d'),width=$('video').videoWidth||640,height=$('video').videoHeight||480;if(canvas.width!==width||canvas.height!==height){canvas.width=width;canvas.height=height;}context.clearRect(0,0,width,height);if(!points)return;context.strokeStyle='#82aaff';context.lineWidth=2.5;for(const [a,b]of edges){context.beginPath();context.moveTo((1-points[a].x)*width,points[a].y*height);context.lineTo((1-points[b].x)*width,points[b].y*height);context.stroke();}context.fillStyle='#e3edff';for(const p of points){context.beginPath();context.arc((1-p.x)*width,p.y*height,4,0,Math.PI*2);context.fill();}}
function trackHand(now){
 if(state.mode!=='camera'||!landmarker)return;
 if($('video').readyState>=2&&$('video').currentTime!==lastVideoTime&&now-lastInference>=45){lastVideoTime=$('video').currentTime;lastInference=now;
  try{const result=landmarker.detectForVideo($('video'),now),points=result.landmarks?.[0];drawHand(points);const gesture=engine.update(points,now);
   if(points){lastSeen=now;$('camera-caption').textContent='Hand detected · local processing';
    const pauseGesture=state.paused?gesture.mode==='palm':gesture.mode==='fist';
    if(pauseGesture){if(holdMode!==gesture.mode){holdMode=gesture.mode;holdSince=now;}clearPointer();$('gesture-label').textContent=state.paused?'Hold open palm to resume…':'Hold fist to pause…';if(now-holdSince>=1000)setPaused(!state.paused);}
    else{holdMode=null;holdSince=0;if(state.paused){clearPointer();$('gesture-label').textContent='Paused · hold an open palm to resume';}
     else if(['point','pinch','scroll'].includes(gesture.mode)){const rect=$('workspace').getBoundingClientRect(),x=rect.left+gesture.x*rect.width,y=rect.top+gesture.y*rect.height,target=pointer(x,y,gesture.mode==='pinch');if(gesture.click&&target)target.click();if(gesture.mode==='scroll'&&!$('document-view').hidden&&!$('files').hidden)$('document-body').scrollTop+=gesture.scrollDelta;$('gesture-label').textContent=gesture.mode==='pinch'?'Pinch · release before selecting again':gesture.mode==='scroll'?'Scroll mode':'Pointing';}else{clearPointer();$('gesture-label').textContent='Raise your index finger to point';}}
   }else{holdMode=null;holdSince=0;clearPointer();$('gesture-label').textContent=state.paused?'Paused · show an open palm to resume':'No hand detected';if(now-lastSeen>1200)$('camera-caption').textContent='Show one hand in view';}
  }catch{stopCamera(false);status('Tracking was interrupted. Restart the camera or continue with mouse and keyboard.',true);return;}
 }frameId=requestAnimationFrame(trackHand);
}
$('camera-button').addEventListener('click',startCamera);$('stop-button').addEventListener('click',()=>stopCamera());$('pause-button').addEventListener('click',()=>setPaused(!state.paused));
$('smoothing').addEventListener('input',event=>{engine.smoothing=Number(event.target.value)/100;$('smoothing-value').textContent=`${event.target.value}%`;});$('sensitivity').addEventListener('input',event=>{engine.threshold=Number(event.target.value)/100;$('sensitivity-value').textContent=engine.threshold<.24?'Deliberate':engine.threshold>.33?'Sensitive':'Balanced';engine.reset();});
document.addEventListener('keydown',event=>{if(event.key==='Escape'){stopDemo();stopCamera();}if(event.code==='Space'&&state.mode==='camera'&&!['INPUT','BUTTON','TEXTAREA','SUMMARY'].includes(event.target.tagName)){event.preventDefault();setPaused(!state.paused);}});
document.addEventListener('visibilitychange',()=>{if(document.hidden){stopDemo();stopCamera();}});window.addEventListener('pagehide',()=>{stopDemo();stopCamera(false);});
// Optional WebMCP bridge. It never starts the camera or grants device permission.
const bridge=document.modelContext;if(bridge?.registerTool){const lifecycle=new AbortController();const register=tool=>{try{Promise.resolve(bridge.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}};register({name:'read_gloveflow_state',description:'Read the simulated practice status. No camera images or landmarks are returned.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({mode:state.mode,paused:state.paused,completedSteps:state.step,selections:state.selections,reviewed:state.step===3})});register({name:'navigate_gloveflow_section',description:'Open Overview, Reference files, or Activity in the simulated workspace. Opening Reference files advances the practice step.',inputSchema:{type:'object',properties:{section:{type:'string',enum:['overview','files','activity']}},required:['section'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||Object.keys(input).length!==1||!['overview','files','activity'].includes(input.section))throw new Error('Expected a valid section.');selectTab(input.section);return {section:input.section,completedSteps:state.step};}});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
